// Renders the profile picture and the X banner from the SVG mark, in the site's register.
//   node brand/render-brand.js   (from the repository root; needs app/node_modules/puppeteer-core)
const puppeteer = require("../app/node_modules/puppeteer-core");
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const mark = fs.readFileSync(path.join(root, "app/public/logo.svg"), "utf8");
const markUri = "data:image/svg+xml;base64," + Buffer.from(mark).toString("base64");
const fonts = `<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Modak&family=Geist:wght@600;700;800&display=swap" rel="stylesheet">`;

const pp = `<!doctype html><meta charset=utf-8>${fonts}<style>
html,body{margin:0;width:1024px;height:1024px;background:#0a0a0b;overflow:hidden}
.wrap{position:relative;width:1024px;height:1024px;display:grid;place-items:center;background:radial-gradient(60% 60% at 50% 42%,#17171a 0%,#0a0a0b 100%)}
img{width:560px;height:auto;display:block;transform:translateY(-14px)}
</style><div class=wrap><img src="${markUri}"></div>`;

const banner = `<!doctype html><meta charset=utf-8>${fonts}<style>
html,body{margin:0;width:1500px;height:500px;background:#0a0a0b;overflow:hidden;font-family:Geist,system-ui,sans-serif}
.wrap{position:relative;width:1500px;height:500px;background:#0a0a0b}
.photo{position:absolute;inset:0;background:url(data:image/jpeg;base64,) center 58%/cover no-repeat}
.veil{position:absolute;inset:0;background:radial-gradient(70% 90% at 62% 50%,rgba(10,10,11,.25),rgba(10,10,11,.7) 100%),linear-gradient(90deg,rgba(10,10,11,.75) 0%,rgba(10,10,11,.45) 30%,rgba(10,10,11,.45) 70%,rgba(10,10,11,.75) 100%),linear-gradient(180deg,rgba(10,10,11,.4),rgba(10,10,11,.15) 40%,rgba(10,10,11,.8))}
.title{position:absolute;left:0;right:0;top:96px;text-align:center;font-family:Modak,system-ui;font-size:108px;line-height:.92;letter-spacing:.01em;color:#fff;text-shadow:0 4px 0 #8e8e9a,0 16px 34px rgba(0,0,0,.7)}
.title b{display:block;font-weight:400;color:#fff312;text-shadow:0 4px 0 #9a8b00,0 16px 34px rgba(0,0,0,.7)}
.tag{position:absolute;left:0;right:0;top:336px;line-height:1.3;text-align:center;font-size:26px;font-weight:600;color:#e6e6ea;letter-spacing:-.01em;text-shadow:0 2px 12px rgba(0,0,0,.8)}
.tag span{color:#fff312}
.chain{position:absolute;left:0;right:0;top:432px;text-align:center;font-size:18px;font-weight:600;color:#a6a6ae;letter-spacing:.04em;text-shadow:0 2px 10px rgba(0,0,0,.8)}
</style><div class=wrap><div class=photo></div><div class=veil></div>
<div class=title>Every street<b>owns a piece.</b></div>
<div class=tag>Photograph a listed company in the wild.<br>Keep the card <span>and a fragment of its stock.</span></div>
<div class=chain>Robinhood Chain · Stock Tokens · bought in advance, nothing minted</div>
</div>`;

(async () => {
  const chrome = "C:/Program Files/Google/Chrome/Application/chrome.exe";
  const browser = await puppeteer.launch({ executablePath: chrome, headless: "new" });
  const page = await browser.newPage();
  const shots = [
    ["pp", pp, 1024, 1024, 1],
    ["banner-x", banner, 1500, 500, 2],
  ];
  for (const [name, html, w, h, scale] of shots) {
    await page.setViewport({ width: w, height: h, deviceScaleFactor: scale });
    await page.setContent(html, { waitUntil: "load", timeout: 60000 });
    await Promise.race([page.evaluate(() => document.fonts.ready.then(() => true)), new Promise((r) => setTimeout(() => r(false), 8000))]);
    await new Promise((r) => setTimeout(r, 400));
    await page.screenshot({ path: path.join(__dirname, `spot-${name}.png`), clip: { x: 0, y: 0, width: w, height: h } });
    console.log("wrote", `brand/spot-${name}.png`, `${w * scale}x${h * scale}`);
  }
  await browser.close();
})();
